# river beds: cut 1.5-5 m into the valley floor, deeper and wider for larger catchments, with soft banks
big = smoothstep(0.003, 0.05, @catchment)
bed = smoothstep(0.05, 0.3, @river + 0.12 * big * @river / (@river + 0.02))
@bed = bed * @land
@C = @C - (1.5 + 3.5 * big) / 2048 * @bed

hm = @C * 2048
flat = 1 - smoothstep(0.015, 0.06, 1 - @Nr.z)
low = smoothstep(4, 12, hm) * (1 - smoothstep(60, 150, hm))
@d_town = flat * low * @land * (1 - smoothstep(0.05, 0.3, @bed))
# no road below 2 m: the beach and the sea
@noroad = max(@sea, 1 - smoothstep(1.0, 2.5, hm))

# the road bed (the ground smoothed along the road) replaces the ground in the corridor, blending out over
# the cut and fill slopes; the sea is left alone
m = smoothstep(0.2, 0.85, @rdw) * @land
@C = lerp(@C, @rdw_road_h / 2048, m)
@road = @road * @land

t = normalize(set(@tangentu.x, 0 * @P.x, @tangentu.z))
s = set(t.z, 0 * @P.x, 0 - t.x) * 1
@P = @P + s * 54.0
@N = s
@up = set(0, 1, 0) + 0 * s
@front = 0 - s

t = normalize(set(@tangentu.x, 0 * @P.x, @tangentu.z))
s = set(t.z, 0 * @P.x, 0 - t.x) * -1
@P = @P + s * 54.0
@N = s
@up = set(0, 1, 0) + 0 * s
@front = 0 - s

@yard = rand(@primnum + 3.3)
@pad_h = (@h_min + @h_max) * 0.5 * 2048
s@name = sprintf("Town_%02d", floor(@ti_max + 0.5).astype(int) + 1)
# taller toward the core of the town
i@floors = clamp(floor(1.0 + 3.2 * smoothstep(0.6, 1.0, @tc_avg) + 1.0 * rand(@primnum + 9.1)), 1, 5)
s@rf = where(@floors >= 4, "hip", "gable")
# the lot's centre: the buildings' LOD is picked by its distance to the camera
@lcx = @P.x
@lcz = @P.z

r = length(set(@u - 0.5, @v - 0.5)) * 280.3
g = clamp((@Grass + 0.35 * @ForestFloor) * (1 - clamp(@rd, 0, 1)) * (1 - @Water), 0, 1)
@gd = g * max(min(1, pow(12 / max(r, 0.5), 2)), 0.05) * (1 - smoothstep(110, 140, r))
# on the close-range ground: the height with the detail relief
@Cdh = @C + @dh / 2048

names = np.array(["Bush_A", "Bush_B"])
s@name = names[(rand(@ptnum + 0.3) * 2).astype(int)]
a = rand(@ptnum + 1.7) * 2 * PI
@N = set(sin(a), 0 * a, cos(a))
@up = normalize(lerp(set(0, 1, 0), @tn, 0.4))
@pscale = 0.9 + 1.2 * rand(@ptnum + 4.1)

s@name = sprintf("SM_Rock_%02d", (rand(@ptnum + 0.9) * 4).astype(int))
# follow the slope (up tilted 70% towards the terrain normal), sunk in a bit
@up = normalize(lerp(set(0, 1, 0), @tn, 0.7))
a = rand(@ptnum + 3.3) * 2 * PI
@N = normalize(cross(@up, set(sin(a), 0 * a, cos(a))))
@pscale = 0.8 + 3.0 * pow(rand(@ptnum + 5.5), 2)
@P.y -= 0.25 * @pscale

@Cd = pow(clamp(@Cd, 0, 1), 1 / 2.2)
# the preview shows the sea surface, not the sea floor (the height files keep the floor)
uw = @P.y < -0.3
@N = where(uw, set(0, 1, 0), @N)
@P.y = max(@P.y, -0.3)

a = rand(@ptnum + 0.7) * 2 * PI
@N = set(sin(a), 0 * a, cos(a))
@up = set(0, 1, 0)
@pscale = 0.6 + 0.7 * rand(@ptnum + 3.1)
# the albedo is linear; Cd is a display colour
@Cd = pow(clamp(@terrain_albedo, 0, 1), 1 / 2.2) * (0.85 + 0.3 * rand(@ptnum + 5.3))
@P.y -= 0.04

v = set(-2300.0, 1250.0, 2600.0) - @P
@far = (length(v) >= 0.0) * 1
# the hemi-octahedral frame looking from this camera (the atlas' 8 x 8 grid)
d = normalize(set(v.x, clamp(v.y, 0, 1e9), v.z))
s = abs(d.x) + abs(d.y) + abs(d.z)
@fi = floor((d.x + d.z) / s * 3.5 + 4.0)
@fj = floor((d.x - d.z) / s * 3.5 + 4.0)
@cn = normalize(set(v.x, 0 * v.y, v.z))

v = set(-1150.0, 230.0, 250.0) - @P
@far = (length(v) >= 500.0) * 1
# the hemi-octahedral frame looking from this camera (the atlas' 8 x 8 grid)
